async (req, res) => {
  try {
    const {
      roomCode
    } = req.body;
    if (!roomCode) {
      return res.status(400).json({
        message: "Room code is required."
      });
    }
    if (req.user.currentRoom) {
      return res.status(400).json({
        message: "You are already in a room."
      });
    }
    const room = await Room.findOne({
      roomCode
    });
    if (!room) {
      return res.status(404).json({
        message: "Room not found."
      });
    }
    if (room.status !== "ACTIVE") {
      return res.status(400).json({
        message: "Room is no longer active."
      });
    }
    if (room.currentMembers >= room.maxMembers) {
      return res.status(400).json({
        message: "Room is full."
      });
    }
    let roomMember = await RoomMember.findOne({
      roomId: room._id,
      userId: req.user._id
    });
    if (roomMember) {
      if (roomMember.isActive) {
        return res.status(400).json({
          message: "You are already in this room."
        });
      }
      roomMember.isActive = true;
      roomMember.joinedAt = new Date();
      roomMember.leftAt = null;
      await roomMember.save();
    } else {
      await RoomMember.create({
        roomId: room._id,
        userId: req.user._id,
        joinedAt: new Date(),
        isActive: true
      });
    }
    if (!room.currentHost) {
      room.currentHost = req.user._id;
    }
    room.currentMembers++;
    await room.save();
    await User.findByIdAndUpdate(req.user._id, {
      currentRoom: room._id
    });
    res.status(200).json({
      message: "Joined room successfully.",
      room: {
        roomId: room._id,
        roomCode: room.roomCode,
        roomName: room.roomName,
        currentMembers: room.currentMembers,
        maxMembers: room.maxMembers
      }
    });
  } catch (err) {
    res.status(500).json({
      message: err.message
    });
  }
}

async (req, res) => {
  try {
    if (!req.user.currentRoom) {
      return res.status(400).json({
        message: "You are not in any room."
      });
    }
    const room = await Room.findById(req.user.currentRoom);
    if (!room) {
      return res.status(404).json({
        message: "Room not found."
      });
    }
    const roomMember = await RoomMember.findOne({
      roomId: room._id,
      userId: req.user._id,
      isActive: true
    });
    if (!roomMember) {
      return res.status(404).json({
        message: "Membership not found."
      });
    }
    roomMember.isActive = false;
    roomMember.leftAt = new Date();
    await roomMember.save();
    await User.findByIdAndUpdate(req.user._id, {
      currentRoom: null
    });
    room.currentMembers--;
    if (room.currentHost && room.currentHost.equals(req.user._id)) {
      const nextHost = await RoomMember.findOne({
        roomId: room._id,
        isActive: true
      }).sort({
        joinedAt: 1
      });
      const io = req.app.get("io");
      if (nextHost) {
        room.currentHost = nextHost.userId;
        newHost = {
          id: nextHost.userId._id.toString(),
          username: nextHost.userId.username
        };
      } else {
        room.currentHost = null;
      }
    }
    await room.save();
    if (newHost) {
      io.to(room._id.toString()).emit("host-changed", newHost);
    }
    res.status(200).json({
      message: "Left room successfully."
    });
  } catch (err) {
    res.status(500).json({
      message: err.message
    });
  }
}

