async (req, res) => {
  try {
    const {
      userId
    } = req.body;
    if (!userId) {
      return res.status(400).json({
        message: "User ID is required."
      });
    }
    if (!req.user.currentRoom) {
      return res.status(400).json({
        message: "You are not in a room."
      });
    }
    const room = await Room.findById(req.user.currentRoom);
    if (!room) {
      return res.status(404).json({
        message: "Room not found."
      });
    }
    if (!room.currentHost || !room.currentHost.equals(req.user._id)) {
      return res.status(403).json({
        message: "Only the current host can remove members."
      });
    }
    if (!room.currentHost.equals(req.user._id)) {
      return res.status(403).json({
        message: "Only the current host can remove members."
      });
    }
    if (req.user._id.equals(userId)) {
      return res.status(400).json({
        message: "Use Leave Room instead."
      });
    }
    if (room.originalHost.equals(userId)) {
      return res.status(400).json({
        message: "Original host cannot be removed."
      });
    }
    const member = await RoomMember.findOne({
      roomId: room._id,
      userId,
      isActive: true
    });
    if (!member) {
      return res.status(404).json({
        message: "Member not found."
      });
    }
    member.leftAt = new Date();
    await member.save();
    await User.findByIdAndUpdate(userId, {
      currentRoom: null
    });
    room.currentMembers--;
    await room.save();
    const io = req.app.get("io");
    io.to(room._id.toString()).emit("member-kicked", {
      userId: userId.toString()
    });
    res.status(200).json({
      message: "Member removed successfully."
    });
  } catch (err) {
    res.status(500).json({
      message: err.message
    });
  }
}

